typedef unsigned int size_t;
extern "C" size_t strlen(const char *);
void *operator new(size_t, unsigned, const char *, int);

class string_buf {
public:
  unsigned long long *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx {
public:
  char *chars;
  string_buf *my_buf;
  stringx();
  stringx(const stringx&);
  ~stringx();
  const char *c_str() const { return chars; }
  void make_room(int);
  void append(const stringx&);
  void append(const char *, int = -1);
  friend stringx operator+(const stringx&, const stringx&);
  friend stringx operator+(const stringx&, const char *);
};

inline stringx operator+(const stringx& lhs, const stringx& rhs) {
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}
inline stringx operator+(const stringx& lhs, const char *rhs) {
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

class script_object {
public:
  class instance {
    stringx name;
  public:
    const stringx& get_name() const { return name; }
  };
};
class vm_executable {
  void *owner;
  stringx name;
  stringx fullname;
public:
  const stringx& get_fullname() const { return fullname; }
};
class vm_thread {
  script_object::instance *inst;
  const vm_executable *ex;
public:
  script_object::instance *get_instance() const { return inst; }
  const vm_executable *get_executable() const { return ex; }
};
class vm_stack {
public:
  int salloc;
  char *buffer;
  char *SP;
private:
  vm_thread *my_thread;
public:
  char *get_SP() const { return SP; }
  void pop(int n) { SP -= n; }
  bool push(const char *, int);
  vm_thread *get_thread() const { return my_thread; }
};

class widget {
public:
  enum rhw_layer_e { RHW0, RHW1, RHW2, RHW3 };
  static rhw_layer_e rhw_3d_layer;
  static rhw_layer_e last_rhw_3d_layer;
  static void set_rhw_3d_layer(rhw_layer_e layer) {
    last_rhw_3d_layer = rhw_3d_layer;
    rhw_3d_layer = layer;
  }
  static void restore_last_rhw_3d_layer() { rhw_3d_layer = last_rhw_3d_layer; }
};
class script_widget_holder_t : public widget {};
class game {
  char pad[60];
  script_widget_holder_t *script_widget_holder;
public:
  script_widget_holder_t *get_script_widget_holder() const { return script_widget_holder; }
};
extern game *g_game_ptr;

class entity_widget : public widget {
  char pad[460];
public:
  entity_widget(const char *, widget *, short, short, const char * = 0);
};
typedef const stringx *vm_str_t;
typedef entity_widget *vm_entity_widget_t;
void error(const stringx&);

class script_library_class {
public:
  class function {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

#define NEW new(0,__PRETTY_FUNCTION__,0)
#define SLF_PARMS stack.pop(sizeof(parms_t)); parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN if (!stack.push((char*)&result,sizeof(result))) error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname())
#define SLF_DONE return true

class slf_create_entity_widget_t : public script_library_class::function {
public:
  struct parms_t { vm_str_t filename; };
  virtual bool operator ()(vm_stack &stack, entry_t entry)
  {
    SLF_PARMS;
    widget::set_rhw_3d_layer( widget::RHW3 );
    vm_entity_widget_t result = NEW entity_widget( "script ent widg", (widget*)(g_game_ptr->get_script_widget_holder()), 0, 0, parms->filename->c_str() );
    widget::restore_last_rhw_3d_layer();
    SLF_RETURN;
    SLF_DONE;
  }
};
